-- Recovery Phase 5: redirects table (management + hit metrics).
-- The Edge middleware keeps resolving via redirect-map.json (fast path); this
-- table is the dashboard's source of truth and stores hitCount/lastHitAt.
CREATE TABLE IF NOT EXISTS `redirects` (
  `id`          CHAR(36) NOT NULL PRIMARY KEY,
  `source`      VARCHAR(512) NOT NULL,            -- stored decoded + lowercased, starts with /
  `destination` VARCHAR(512) NOT NULL,
  `status_code` INT NOT NULL DEFAULT 301,         -- 301 | 302 | 410
  `is_active`   TINYINT(1) NOT NULL DEFAULT 1,
  `is_regex`    TINYINT(1) NOT NULL DEFAULT 0,
  `priority`    INT NOT NULL DEFAULT 0,           -- higher wins; exact(10) above pattern(1)
  `hit_count`   INT NOT NULL DEFAULT 0,
  `last_hit_at` DATETIME NULL,
  `note`        VARCHAR(512) NULL,
  `created_by`  VARCHAR(191) NULL,
  `created_at`  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_source` (`source`),
  KEY `ix_active_priority` (`is_active`, `priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seed from redirect-map.json. Idempotent: keeps existing rows/hit counts.
ON DUPLICATE KEY UPDATE `destination`=VALUES(`destination`), `status_code`=VALUES(`status_code`), `is_regex`=VALUES(`is_regex`), `priority`=VALUES(`priority`);
